#define waveSpeed 0.1
#define waveWidth 0.03
const int waves = 5;
float loop(float angle)
{
    return(sin(angle)+1.0)/2.0;
}
bool isRing(vec2 origin, vec2 point, float interval, float width)
{
    float _distance = distance(origin, point);
    return mod(_distance, interval) <= width;
}
bool isRingOffset(vec2 origin, vec2 point, float interval, float width, float offset)
{
    float _distance = distance(origin, point) + offset;
    return loop(_distance) <= width;
}
float ring(vec2 origin, vec2 point, float speed, float width, float offset)
{
    vec2 way = point - origin;
    return sin(((sqrt(pow(way.x,2.0)+pow(way.y,2.0))+offset*speed)/width));
    /*float _distance = distance(origin, point) + offset*speed;
    return sin(_distance/width);*/
}
#define rot(a) mat2(cos(a+vec4(0,11,33,0)))

//formula for creating colors;
#define H(h)  (  cos( h*2. + 7.*vec3(1,2,3) )*.4 + .3 )

//formula for mapping scale factor 
#define M(c)  log(1.+c)

#define R iResolution
vec2 ringDifferential(vec2 origin, vec2 point, float speed, float width, float offset)
{
    vec2 way = point - origin;
    float wayLength = length(way);
    float x = (way.x*cos((wayLength + offset*speed)/width))/width*wayLength;
    float y = (way.y*cos((wayLength + offset*speed)/width))/width*wayLength;
    return vec2(x,y);
}

vec2 waveOrigins[waves];


float wave(vec2 point)
{
    float height = 0.0;
    for(int i = 0; i < waves; i++)
    {
        height += ring(waveOrigins[i], point, waveSpeed, waveWidth, -iTime);
    }
    return height;
}
#define Pi 3.1415926535897932384626433832795
#define Distortion 0.5*1.*(sin(iTime-0.5*Pi)+1.)

float GetRot(vec2 uv, vec2 a){
    vec2 b = uv-a;
    b.x *= iResolution.x/iResolution.y;
    vec2 j = vec2(0., 1.);
    return acos(dot(b,j)/length(b))*(abs(mod(b.x, 4.*Pi)-2.*Pi)/(2.*Pi-mod(b.x, 4.*Pi)));
}

float f(float a, float x){
    return 0.5*(sin(x-0.5*Pi)+1.)*a;
}

vec2 differentialWave(vec2 point)
{
    vec2 distortion = vec2(0.0);
    for(int i = 0; i < waves; i++)
    {
        distortion += ringDifferential(waveOrigins[i], point, waveSpeed, waveWidth, -iTime);
    }
    return distortion;
}

#define NUM_OCTAVES 5

float rand(in vec2 _st) {
    return fract(sin(dot(_st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

float noise(vec2 p){
	vec2 ip = floor(p);
	vec2 u = fract(p);
	u = u*u*(3.0-2.0*u);

	float res = mix(
		mix(rand(ip),rand(ip+vec2(1.0,0.0)),u.x),
		mix(rand(ip+vec2(0.0,1.0)),rand(ip+vec2(1.0,1.0)),u.x),u.y);
	return res*res;
}

float fbm(vec2 x) {
	float v = 0.0;
	float a = 0.5;
	vec2 shift = vec2(100);
	for (int i = 0; i < NUM_OCTAVES; ++i) {
		v += a * noise(x);
		x = x * 2.0 + shift;
		a *= 0.5;
	}
	return v;
}
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}

